<div class="page-heading"><div><p class="eyebrow">Vendor workspace</p><h1>Sales and order reports</h1><p>Reports use completed orders saved in CampusBite.</p></div></div>
<form class="filter-bar report-filter" method="get" action="<?= h(app_url('vendor.reports')) ?>"><input type="hidden" name="r" value="vendor.reports"><div class="form-field"><label for="start">From</label><input id="start" type="date" name="start" value="<?= h($start) ?>" required></div><div class="form-field"><label for="end">To</label><input id="end" type="date" name="end" value="<?= h($end) ?>" required></div><button class="button" type="submit">Apply dates</button></form>
<div class="kpi-grid" style="margin-top:15px"><div class="kpi"><span class="kpi-label">Cash sales</span><strong class="kpi-value"><?= h(money($range['sales'] ?? 0)) ?></strong><span class="kpi-note">By pickup/completion date</span></div><div class="kpi"><span class="kpi-label">Orders placed</span><strong class="kpi-value"><?= (int) ($range['order_count'] ?? 0) ?></strong><span class="kpi-note">By order date</span></div><div class="kpi"><span class="kpi-label">Completed</span><strong class="kpi-value"><?= (int) ($range['completed_count'] ?? 0) ?></strong><span class="kpi-note">Cash paid in range</span></div><div class="kpi"><span class="kpi-label">Average fulfillment time</span><strong class="kpi-value"><?= $range['avg_fulfillment'] !== null ? round((float) $range['avg_fulfillment']) . ' min' : '—' ?></strong><span class="kpi-note">Vendor accepted to pickup completion</span></div></div>
<div class="dashboard-grid"><section class="panel"><h2 class="panel-title">Sales by day</h2><?php if ($daily): ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Completed sales</th><th>Transactions</th></tr></thead><tbody><?php foreach ($daily as $row): ?><tr><td><?= h(format_datetime($row['day'], 'D, M j')) ?></td><td><?= h(money($row['sales'])) ?></td><td><?= (int) $row['transactions'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No completed sales in this date range.</p><?php endif; ?></section>
<section class="panel"><h2 class="panel-title">Best-selling foods</h2><?php if ($best): ?><div class="activity-list"><?php foreach ($best as $food): ?><div class="activity-item"><span class="activity-dot" aria-hidden="true"></span><div class="spread"><strong><?= h($food['food_name']) ?></strong><span class="muted small"><?= (int) $food['units'] ?> sold · <?= h(money($food['sales'])) ?></span></div></div><?php endforeach; ?></div><?php else: ?><p class="muted">No completed food sales in this range.</p><?php endif; ?></section></div>
<section class="panel" style="margin-top:16px"><h2 class="panel-title">Low stock</h2><?php if ($lowStock): ?><div class="table-wrap"><table><thead><tr><th>Food</th><th>On hand</th><th>Threshold</th></tr></thead><tbody><?php foreach ($lowStock as $item): ?><tr><td><?= h($item['name']) ?></td><td><?= h(number_format((float) $item['quantity'],2)) ?> <?= h($item['unit']) ?></td><td><?= h(number_format((float) $item['low_stock_threshold'],2)) ?> <?= h($item['unit']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">All tracked foods are above their low-stock threshold.</p><?php endif; ?></section>
